#ifndef EMPLOYEE_SCHEDULE_H
#define EMPLOYEE_SCHEDULE_H
#define EMPLOYEE_SCHEDULE_HTML "<section id='employeeSchedule' hidden><h2>Schedule</h2><p id='es-schedbanner' role='alert' hidden></p><section><input id='es-emp' type='hidden'><p id='es-empflag' role='status'></p><label>Schedule type<select id='es-type'><option value=''>Choose a schedule</option><option value='recurring_weekly'>Recurring weekly</option><option value='dated_shifts'>Dated shifts</option><option value='none'>No fixed schedule</option></select></label><div id='es-weekly'><p class='muted'>Working days and times. If the end is earlier, the shift ends the following day.</p><div id='es-days'></div><label>Start <input id='es-start' type='time' value='09:00'></label><label>End <input id='es-end' type='time' value='17:00'></label></div><div class='actions'><button id='es-profile'>Save schedule</button></div></section><section id='es-hourly'><h2>Dated shifts</h2><p class='muted'>Saved dated shifts are kept when you change schedule type. They become active again if you return to Dated shifts. Check upcoming dates before saving.</p><label>Date <input id='es-date' type='date'></label><label>Start <input id='es-shiftstart' type='time' value='09:00'></label><label>End <input id='es-shiftend' type='time' value='17:00'></label><div class='actions'><button id='es-add'>Add dated shift</button></div><div class='table-scroll'><table><thead><tr><th>Date</th><th>Time</th><th></th></tr></thead><tbody id='es-shifts'></tbody></table></div></section><section><p id='es-status' role='status'></p><p class='muted'>Changes are logged. Punches already recorded are not changed.</p></section></section>"
#define EMPLOYEE_SCHEDULE_JS "<script>(()=>{let all={employees:[],shifts:[]};const el=id=>document.getElementById('es-'+id);let busy=false;const dn=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];el('days').replaceChildren(...dn.map((n,i)=>{let l=document.createElement('label'),c=document.createElement('input');c.type='checkbox';c.dataset.bit=String(1<<i);l.append(c,document.createTextNode(n));return l}));const api=tc.api;async function load(){all=await api('/api/v1/admin/schedules');render()}function issue(e,today){if(e.attendance_mode==='vacation_only'||e.schedule_mode==='none'||e.schedule_exempt)return '';if(!e.has_card)return '';if(e.schedule_mode==='unconfigured')return 'No schedule';if(e.schedule_mode==='dated_shifts'&&!all.shifts.some(x=>x.employee_id===e.id&&x.date>=today))return 'No upcoming shifts';return ''}function render(){let e=all.employees.find(x=>String(x.id)===el('emp').value);if(!e){document.getElementById('employeeSchedule').hidden=true;return}let f=issue(e,tc.date(new Date()));el('empflag').replaceChildren();if(e.schedule_mode==='none')el('empflag').append(tc.flag('No fixed schedule','muted'));if(f)el('empflag').append(tc.flag(f,'check'),f==='No schedule'?' Save a schedule for this employee.':' Add shifts below.');el('type').value=e.schedule_mode==='unconfigured'?'':e.schedule_mode;el('start').value=e.start||'09:00';el('end').value=e.end||'17:00';for(let x of el('days').querySelectorAll('input'))x.checked=!!(e.mask&Number(x.dataset.bit));el('hourly').hidden=el('type').value!=='dated_shifts';el('weekly').hidden=el('type').value!=='recurring_weekly';el('shifts').replaceChildren();for(let s of all.shifts.filter(x=>x.employee_id===e.id)){let row=document.createElement('tr'),d=document.createElement('td'),t=document.createElement('td'),a=document.createElement('td'),b=document.createElement('button');d.textContent=s.date;t.textContent=s.start+' - '+s.end;b.textContent='Delete';b.onclick=()=>save({op:'delete',employee_id:e.id,shift_id:s.id});a.append(b);row.append(d,t,a);el('shifts').append(row)}}el('emp').onchange=render;el('type').onchange=()=>{el('hourly').hidden=el('type').value!=='dated_shifts';el('weekly').hidden=el('type').value!=='recurring_weekly'};async function save(obj){if(busy)return;busy=true;el('status').textContent='Saving...';try{const j=await api('/api/v1/admin/schedules/save',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(obj)});if(j.status!=='saved')throw Error('Schedule not saved.');await load();tc.ok(el('status'),'Schedule saved.');}catch(e){tc.err(el('status'),e)}finally{busy=false}}el('profile').onclick=()=>{let mask=0;for(let c of el('days').querySelectorAll('input'))if(c.checked)mask|=Number(c.dataset.bit);(()=>{const t=el('type').value,s=el('start').value,e=el('end').value;if(!t)return tc.err(el('status'),Error('Choose a schedule type.'));if(t==='recurring_weekly'&&!mask)return tc.err(el('status'),Error('Choose at least one working day.'));if(!s||!e)return tc.err(el('status'),Error('Enter a start and end time.'));if(s===e)return tc.err(el('status'),Error('Start and end times must be different.'));save({op:'profile',employee_id:el('emp').value,type:t,start:s,end:e,mask})})()};el('add').onclick=()=>save({op:'shift',employee_id:el('emp').value,date:el('date').value,start:el('shiftstart').value,end:el('shiftend').value});window.employeeSchedule={open:async(id,only)=>{el('emp').value=String(id);document.getElementById('employeeSchedule').hidden=!id||only;if(id)try{await load()}catch(e){tc.err(el('status'),e)}},visibility:only=>{document.getElementById('employeeSchedule').hidden=only||!Number(el('emp').value)}}})();</script>"
#endif
